import {
  CircleAlert,
  CircleCheck,
  Info,
  TriangleAlert,
  type LucideIcon,
} from 'lucide-react'
import type { ReactNode } from 'react'

import { cx } from '~/lib/cx'
import styles from './result.module.scss'

export type ResultTone = 'success' | 'info' | 'warning' | 'error'

const TONE: Record<ResultTone, string> = {
  success: styles.success,
  info: styles.info,
  warning: styles.warning,
  error: styles.error,
}

const ICON: Record<ResultTone, LucideIcon> = {
  success: CircleCheck,
  info: Info,
  warning: TriangleAlert,
  error: CircleAlert,
}

export interface ResultProps {
  tone?: ResultTone
  title: string
  description?: ReactNode
  actions?: ReactNode
  className?: string
}

/** Full-section outcome state for success, empty, error and warning pages. */
export function Result({
  tone = 'info',
  title,
  description,
  actions,
  className,
}: ResultProps) {
  const Icon = ICON[tone]

  return (
    <section className={cx(styles.root, TONE[tone], className)}>
      <span className={styles.icon}>
        <Icon aria-hidden />
      </span>
      <h2 className={styles.title}>{title}</h2>
      {description ? <p className={styles.description}>{description}</p> : null}
      {actions ? <div className={styles.actions}>{actions}</div> : null}
    </section>
  )
}

@use 'styles' as vz;

.root {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: vz.space(3);
  padding: vz.space(10) vz.space(6);
  border: 1px solid vz.color('border');
  border-radius: vz.radius('2xl');
  background: vz.color('card');
  text-align: center;
}

.icon {
  display: inline-flex;
  width: vz.space(12);
  height: vz.space(12);
  align-items: center;
  justify-content: center;
  border-radius: vz.radius('full');
  background: var(--result-tint);

  svg {
    @include vz.icon(6);
  }
}

.success {
  --result-color: #{vz.color('success')};
  --result-tint: #{vz.color('success', 0.12)};
}

.info {
  --result-color: #{vz.color('info')};
  --result-tint: #{vz.color('info', 0.12)};
}

.warning {
  --result-color: #{vz.color('warning')};
  --result-tint: #{vz.color('warning', 0.14)};
}

.error {
  --result-color: #{vz.color('destructive')};
  --result-tint: #{vz.color('destructive', 0.12)};
}

.icon {
  color: var(--result-color);
}

.title {
  margin: 0;
  font-size: vz.font-size('xl');
  font-weight: 700;
  letter-spacing: -0.02em;
}

.description {
  margin: 0;
  max-width: 32rem;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('sm');
  line-height: 1.55;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: vz.space(2);
  padding-top: vz.space(1);
}
